    expectFailureWhenTestingThat(array(1.1, TOLERABLE_2POINT2, 3.3))
        .usingTolerance(DEFAULT_TOLERANCE)
        .containsExactly(array(2.2, 1.1));
    assertFailureKeys(
        "value of", "unexpected (1)", "---", "expected", "testing whether", "but was");
