<COVER>          new Correspondence.BinaryPredicate<Double, Number>() {
            @Override
            public boolean apply(Double actual, Number expected) {
<COVER>              return Double.doubleToLongBits(actual)
<COVER>                  == Double.doubleToLongBits(checkedToDouble(expected));
            }
          },
          "is exactly equal to");

