  private final float @Nullable [] actual;

  PrimitiveFloatArraySubject(
      FailureMetadata metadata, float @Nullable [] o, @Nullable String typeDescription) {
<COVER>    super(metadata, o, typeDescription);
<COVER>    this.actual = o;
