<COVER>    return new Factory<IterableSubject, Iterable<?>>() {
      @Override
      public IterableSubject createSubject(FailureMetadata metadata, @Nullable Iterable<?> actual) {
<COVER>        return new IterableSubjectWithInheritedToString(metadata, actual);
