  }

  private final class IterableSubjectWithInheritedToString extends IterableSubject {

<COVER>    IterableSubjectWithInheritedToString(FailureMetadata metadata, @Nullable Iterable<?> actual) {
<COVER>      super(metadata, actual);
    }

