public class PrimitiveFloatArraySubjectTest extends BaseSubjectTestCase {

  @Test
  public void usingExactEquality_containsExactly_incorrectOrder_fails() {
    try {
      expectFailureWhenTestingThat(array(1.1f, 2.2f, 3.3f))
          .usingExactEquality()
          .containsExactly(array(2.2f, 1.1f, 3.3f));
      fail("Expected an AssertionError due to incorrect order, but none was thrown.");
    } catch (AssertionError expected) {
      assertThat(expected).hasMessageThat()
          .contains("value of");
      assertThat(expected).hasMessageThat()
          .contains("contents match, but order was wrong");
      assertThat(expected).hasMessageThat()
          .contains("[2.2f, 1.1f, 3.3f]");
    }
  }

  private static float[] array(float... primitives) {
    return primitives;
  }

  private PrimitiveFloatArraySubject expectFailureWhenTestingThat(float[] actual) {
    return new PrimitiveFloatArraySubject(getFailureMetadata(), actual, "float array");
  }

  // Modified to use a constructor instead of simpleMetadata()
  private FailureMetadata getFailureMetadata() {
    return new FailureMetadata();
  }
}

