  public static Factory<TruthFailureSubject, AssertionError> truthFailures() {
<COVER>    return FACTORY;
  }

<COVER>  private static final Factory<TruthFailureSubject, AssertionError> FACTORY =
<COVER>      new Factory<TruthFailureSubject, AssertionError>() {
        @Override
