<COVER>    StandardSubjectBuilder check =
<COVER>        index == null ? check("factValue(%s)", key) : check("factValue(%s, %s)", key, index);
<COVER>    return check.that(value);
  }

  private static ImmutableList<Fact> factsWithName(ErrorWithFacts error, String key) {
<COVER>    ImmutableList.Builder<Fact> facts = ImmutableList.builder();
<COVER>    for (Fact fact : error.facts()) {
<COVER>      if (fact.key.equals(key)) {
<COVER>        facts.add(fact);
      }
    }
