      String subject = checkNotNull(actual);
      for (int subjectOffset = 0;
          subjectOffset <= subject.length() - string.length();
          subjectOffset++) {
        if (subject.regionMatches(
            /* ignoreCase= */ true,
            /* toffset= */ subjectOffset,
            /* other= */ string,
            /* ooffset= */ 0,
            /* len= */ string.length())) {
