  private static Map<@Nullable Object, @Nullable Object> accumulateMap(
      String functionName, @Nullable Object k0, @Nullable Object v0, @Nullable Object... rest) {
<COVER>    checkArgument(
        rest.length % 2 == 0,
        "There must be an equal number of key/value pairs "
            + "(i.e., the number of key/value parameters (%s) must be even).",
        rest.length + 2);

<COVER>    Map<@Nullable Object, @Nullable Object> expectedMap = Maps.newLinkedHashMap();
<COVER>    expectedMap.put(k0, v0);
<COVER>    Multiset<@Nullable Object> keys = LinkedHashMultiset.create();
