<COVER>      Object key = rest[i];
<COVER>      expectedMap.put(key, rest[i + 1]);
<COVER>      keys.add(key);
    }
<COVER>    checkArgument(
<COVER>        keys.size() == expectedMap.size(),
        "Duplicate keys (%s) cannot be passed to %s().",
        keys,
        functionName);
<COVER>    return expectedMap;
