  public final void containsEntry(@Nullable Object key, @Nullable Object value) {
<COVER>    Map.Entry<@Nullable Object, @Nullable Object> entry = immutableEntry(key, value);
<COVER>    checkNotNull(actual);
<COVER>    if (!actual.entrySet().contains(entry)) {
<COVER>      List<@Nullable Object> keyList = singletonList(key);
<COVER>      List<@Nullable Object> valueList = singletonList(value);
<COVER>      if (actual.containsKey(key)) {
<COVER>        Object actualValue = actual.get(key);
        /*
