  public final class UsingCorrespondence<A extends @Nullable Object, E extends @Nullable Object> {

    private final Correspondence<? super A, ? super E> correspondence;

<COVER>    private UsingCorrespondence(Correspondence<? super A, ? super E> correspondence) {
<COVER>      this.correspondence = checkNotNull(correspondence);
    }

    /**
