<COVER>        A actualValue = getCastSubject().get(expectedKey);
<COVER>        Correspondence.ExceptionStore exceptions = Correspondence.ExceptionStore.forMapValues();
<COVER>        if (correspondence.safeCompare((A) actualValue, expectedValue, exceptions)) {
          // The expected key had the expected value. There's no need to check exceptions here,
          // because if Correspondence.compare() threw then safeCompare() would return false.
<COVER>          return;
