            Map<? extends K, ? extends A> actual,
            Map<? extends K, ? extends E> expected,
            boolean allowUnexpected,
            ValueTester<? super A, ? super E> valueTester) {
<COVER>      Map<K, A> unexpected = new LinkedHashMap<>(actual);
<COVER>      Map<K, E> missing = new LinkedHashMap<>();
<COVER>      Map<K, ValueDifference<A, E>> wrongValues = new LinkedHashMap<>();
<COVER>      for (Map.Entry<? extends K, ? extends E> expectedEntry : expected.entrySet()) {
