<COVER>      return new MapDifference<>(
<COVER>          missing, unexpected, wrongValues, Sets.union(actual.keySet(), expected.keySet()));
    }

    private MapDifference(
        Map<K, E> missing,
        Map<K, A> unexpected,
        Map<K, ValueDifference<A, E>> wrongValues,
<COVER>        Set<K> allKeys) {
<COVER>      this.missing = missing;
<COVER>      this.unexpected = unexpected;
<COVER>      this.wrongValues = wrongValues;
<COVER>      this.allKeys = allKeys;
