@RunWith(JUnit4.class)
public class DoubleSubjectTest extends BaseSubjectTestCase {

  @Test
  public void isEqualTo_handlesEdgeCases() {
    // 1. Next value after the minimum double value towards positive infinity
    assertThat(Math.nextAfter(Double.MIN_VALUE, Double.POSITIVE_INFINITY))
        .isEqualTo(9.9E-324);

    // 2. Next value after the golden value towards positive infinity
