    // 4. Next value after negative maximum towards zero
    assertThat(Math.nextAfter(-Double.MAX_VALUE, 0.0))
        .isEqualTo(-1.7976931348623155E308);

    // 5. Next value after negative minimum towards negative infinity
    assertThat(Math.nextAfter(-Double.MIN_VALUE, Double.NEGATIVE_INFINITY))
        .isEqualTo(-9.9E-324);
  }

