    public void isNotEqualTo_correctlyIdentifiesNonEqualValues() {
        // Test with different values
        assertThat(VALUE_ONE).isNotEqualTo(VALUE_TWO);

        // Test when comparing a value to itself should fail
        expectFailureWhenTestingThat(VALUE_ONE).isNotEqualTo(VALUE_ONE);

