        assertThat(VALUE_ONE).isNotEqualTo(null);
        assertThat(VALUE_ONE).isNotEqualTo(2.0f);
        assertThat(VALUE_ONE).isNotEqualTo(2);
    }

    private DoubleSubject expectFailureWhenTestingThat(double actual) {
        return expectFailure.whenTesting().that(actual);
    }
