import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

@RunWith(JUnit4.class)
public class MathUtilTest {

  @Test
  public void floatNotEquals() {
    // When two equal floats are compared with a small tolerance, the method returns false.
    assertThat(notEqualWithinTolerance(1.3f, 1.3f, 0.0001f)).isFalse();

    // When two floats are exactly the same, the method returns false.
    assertThat(notEqualWithinTolerance(2.5f, 2.5f, 0.0f)).isFalse();

    // When floats are almost equal and within the specified tolerance, the method returns false.
    assertThat(notEqualWithinTolerance(3.1415f, 3.1416f, 0.0002f)).isFalse();

    // When floats differ more than the tolerance, the method returns true.
    assertThat(notEqualWithinTolerance(4.0f, 4.5f, 0.4f)).isTrue();

    // Comparisons involving infinity return false because they are considered equal.
    assertThat(notEqualWithinTolerance(Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY, 0.01f)).isFalse();
    assertThat(notEqualWithinTolerance(Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, 0.01f)).isFalse();

    // Comparisons between positive and negative infinity return false.
    assertThat(notEqualWithinTolerance(Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY, 0.01f)).isFalse();

    // Comparisons involving NaN return false.
    assertThat(notEqualWithinTolerance(Float.NaN, Float.NaN, 0.01f)).isFalse();
  }

}

