import org.junit.rules.ExpectedException;

@RunWith(JUnit4.class)
public class ThrowableSubjectTest extends BaseSubjectTestCase {

  @Rule
  public final ExpectedException expectFailure = ExpectedException.none();

  @Test
  public void hasCauseThat_deepNulls_failure() {
    IOException ioException = new IOException("IO issue");
    RuntimeException runtimeException = new RuntimeException("Runtime issue", ioException);
    Exception actual = new Exception("Top exception", runtimeException);

    expectFailure.expect(AssertionError.class);
    expectFailure.expectMessage("Causal chain is not deep enough - add a .isNotNull() check?");
    expectFailure.expectMessage("value of: throwable.getCause().getCause().getCause()");

    expectFailureWhenTestingThat(actual).hasCauseThat().hasCauseThat().hasCauseThat().isNull();
  }

  private static void assertErrorHasActualAsCause(Throwable actual, AssertionError failure) {
    assertWithMessage("AssertionError's cause").that(failure.getCause()).isEqualTo(actual);
  }

  private ThrowableSubject expectFailureWhenTestingThat(Throwable actual) {
    return assertThat(actual);
  }
}

